import subprocess
import whois

@tool
def get_registrar(domain: str) -> str:
    registrar = whois.whois(domain).registrar
    if not registrar:
        try:
            result = subprocess.run(['whois', domain], capture_output=True, text=True, timeout=15)
            for line in result.stdout.splitlines():
                if line.strip().lower().startswith('registrar:'):
                    registrar = line.split(':', 1)[1].strip()
                    break
        except (OSError, subprocess.TimeoutExpired):
            pass
    return registrar

