@tool
def bash(command: str) -> str:
    result = subprocess.run(command, shell=True, capture_output=True, text=True, stdin=subprocess.DEVNULL)
    output = result.stdout
    if result.stderr:
        output += '\nSTDERR:\n' + result.stderr
    return output or '(no output)'

