        app.logger.error(f'Failed to create Zoom meeting: {e}')
    try:
        subject = 'Your Appointment Confirmation'
        body = make_confirmation_message(name, date, std_time, purpose, join_url)
        send_email(to_address=email, subject=subject, body=body)
    except Exception as e:
        app.logger.error(f'Email send error for {email}: {e}')
    try:
        grant_appointment_role(appointment_date=date, appointment_time=std_time, user_email=email, role='owner')
    except Exception as e:
        app.logger.error(f'Failed to grant owner role to {email}: {e}')
    return f'✅ Appointment booked for **{name}** on **{date}** at **{std_time}** for **{purpose}**. A confirmation email has been sent to {email}.'

