@tool
def send_sms(to_number, msg):
    try:
        message = client.messages.create(to=to_number, from_=TWILIO_NUMBER, body=msg)
        canceled = 0
        for pending in client.messages.list(to=to_number, from_=TWILIO_NUMBER):
            if pending.sid != message.sid and pending.status == 'scheduled':
                client.messages(pending.sid).update(status='canceled')
                canceled += 1
        return f'Message sent successfully. SID: {message.sid}. Canceled {canceled} scheduled message(s).'
    except Exception as e:
        return f'Failed to send SMS: {str(e)}'

